package io.github.foodjournal.infrastructure.openai;
import com.fasterxml.jackson.databind.*; import io.github.foodjournal.application.*; import io.github.foodjournal.config.BotProperties; import java.util.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class OpenAiIntentInterpreter implements IntentInterpreter {
 private final RestClient client; private final BotProperties props; private final ObjectMapper mapper;
 public OpenAiIntentInterpreter(RestClient.Builder builder,BotProperties props,ObjectMapper mapper){this.client=builder.baseUrl("https://api.openai.com/v1").build();this.props=props;this.mapper=mapper;}
 public JournalIntent interpret(String message){ if(props.openaiApiKey()==null||props.openaiApiKey().isBlank()) return new JournalIntent(IntentType.LOG_MEAL,message,null,null,null,null,null,null,List.of()); try { Map<String,Object> body=Map.of("model",props.openaiModel(),"response_format",Map.of("type","json_object"),"messages",List.of(Map.of("role","system","content","Return JSON only: type LOG_MEAL|QUERY_JOURNAL|EDIT_ENTRY|DELETE_ENTRY|UPDATE_SETTINGS|CHAT, mealDescription, calories, query, entryId, timezone, calorieTarget, reportsEnabled, items. Never invent entry IDs."),Map.of("role","user","content",message))); JsonNode json=client.post().uri("/chat/completions").header("Authorization","Bearer "+props.openaiApiKey()).body(body).retrieve().body(JsonNode.class); String content=json.at("/choices/0/message/content").asText(); return mapper.readValue(content,JournalIntent.class); } catch(Exception ex) { return new JournalIntent(IntentType.CHAT,null,null,null,null,null,null,null,List.of()); } }
}
